function renderReportCharts(){api.campaigns.summary().success((function(e){var a=e&&e.campaigns?e.campaigns.slice():[];a.sort((function(t,e){return moment.utc(t.created_date).valueOf()-moment.utc(e.created_date).valueOf()}));var r=a.slice(-8),n=[],s=[];$.each(r,(function(t,e){var a=e.stats&&e.stats.total||0,r=e.stats&&e.stats.clicked||0;n.push(e.name||"#"+e.id),s.push(a?Math.round(r/a*1e3)/10:0)})),n.length&&$("#reportTrendChart").length&&Highcharts.chart("reportTrendChart",{chart:{type:"areaspline",backgroundColor:"transparent"},title:{text:null},credits:{enabled:!1},legend:{enabled:!1},xAxis:{categories:n,labels:{rotation:-25}},yAxis:{min:0,max:100,title:{text:"%"}},series:[{name:t("results.phish_prone"),data:s,color:"#1b7a55",fillOpacity:.15}]})})),api.campaigns.breakdown().success((function(e){var a=e&&e.by_department?e.by_department.slice(0,8):[];a.length&&$("#reportDeptChart").length&&Highcharts.chart("reportDeptChart",{chart:{type:"bar",backgroundColor:"transparent"},title:{text:null},credits:{enabled:!1},legend:{enabled:!1},xAxis:{categories:a.map((function(t){return t.department})),title:{text:null}},yAxis:{min:0,max:100,title:{text:"%"}},series:[{name:t("results.dept_click_rate"),data:a.map((function(t){return Math.round(1e3*(t.click_rate||0))/10})),color:"#1b7a55"}]})}))}$((function(){renderReportCharts()}));